public async Task FetchWithTimeoutAsync(string url, TimeSpan timeout, CancellationToken userCancel)
{
    using var timeoutCts = new CancellationTokenSource(timeout);
    using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(timeoutCts.Token, userCancel);

    try
    {
        using var response = await _httpClient.GetAsync(url, linkedCts.Token);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(linkedCts.Token);
    }
    catch (OperationCanceledException)
    {
        if (timeoutCts.IsCancellationRequested)
            throw new TimeoutException("Request timed out.");

        throw; // Re-throw user-initiated cancellation
    }
}
